      blocks: [{
        label: "Tujuan",
        text: "Mengenali struktur pelajaran: konsep inti, contoh, aktivitas, dan refleksi. Saat modul final tersedia, bagian ini akan diganti dengan materi asli."
      }, {
        label: "Contoh Pengayaan",
        text: "Siswa dapat diajak mengamati contoh teknologi, mendiskusikan dampaknya, lalu membuat proyek mini sederhana sesuai topik modul."
      }, {
        label: "Refleksi",
        text: "Catat hal yang sudah dipahami, hal yang masih membingungkan, dan ide aktivitas yang cocok untuk kelas."
      }],
      activity: "Buat satu pertanyaan yang ingin kamu jawab saat modul KKA/AI final tersedia.",
      checks: ["Apa tujuan pelajaran ini?", "Aktivitas apa yang cocok?", "Apa pertanyaanmu?", "Bagaimana mengukur pemahaman?"]
